import json
import funckit

def run(data_path, out_path):
    with open(data_path, "r") as f:
        data = json.load(f)

    result = {}

    if "shares" in data and "counts" in data["shares"]:
        result["shares"] = funckit.proportions(data["shares"]["counts"])

    if "summaries" in data and "series" in data["summaries"]:
        summaries = {}
        for name, series_data in data["summaries"]["series"].items():
            summaries[name] = funckit.summarize(series_data)
        result["summaries"] = summaries

    if "merged" in data:
        base = data["merged"].get("base", {})
        patch = data["merged"].get("patch", {})
        result["merged"] = funckit.merge(base, patch)

    with open(out_path, "w") as f:
        json.dump(result, f)

